import{_ as n}from"./plugin-vue_export-helper-c27b6911.js";import{o as s,c as a,a as t}from"./app-44772804.js";const e={},o=t(`<h1 id="namedtuple" tabindex="-1"><a class="header-anchor" href="#namedtuple" aria-hidden="true">#</a> namedtuple</h1><p><code>namedtuple</code> 是 Python <code>collections</code> 模块中的一个工厂方法，它用于创建<strong>不可变的、可读性强的元组对象</strong>。它类似于 <code>tuple</code>，但允许你使用<strong>字段名称</strong>来访问元素，而不是使用索引。</p><hr><h2 id="_1-namedtuple-的基本使用" tabindex="-1"><a class="header-anchor" href="#_1-namedtuple-的基本使用" aria-hidden="true">#</a> <strong>1. namedtuple 的基本使用</strong></h2><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">from</span> collections <span class="token keyword">import</span> namedtuple

<span class="token comment"># 创建一个 namedtuple 类型</span>
Person <span class="token operator">=</span> namedtuple<span class="token punctuation">(</span><span class="token string">&#39;Person&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;age&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;city&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span>

<span class="token comment"># 创建 namedtuple 实例</span>
p <span class="token operator">=</span> Person<span class="token punctuation">(</span>name<span class="token operator">=</span><span class="token string">&quot;Alice&quot;</span><span class="token punctuation">,</span> age<span class="token operator">=</span><span class="token number">25</span><span class="token punctuation">,</span> city<span class="token operator">=</span><span class="token string">&quot;New York&quot;</span><span class="token punctuation">)</span>

<span class="token comment"># 访问字段</span>
<span class="token keyword">print</span><span class="token punctuation">(</span>p<span class="token punctuation">.</span>name<span class="token punctuation">)</span>  <span class="token comment"># 输出: Alice</span>
<span class="token keyword">print</span><span class="token punctuation">(</span>p<span class="token punctuation">.</span>age<span class="token punctuation">)</span>   <span class="token comment"># 输出: 25</span>
<span class="token keyword">print</span><span class="token punctuation">(</span>p<span class="token punctuation">.</span>city<span class="token punctuation">)</span>  <span class="token comment"># 输出: New York</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>🔹 <strong>与普通 <code>tuple</code> 的区别</strong>：</p><ul><li>普通 <code>tuple</code> 只能通过索引访问，<code>namedtuple</code> 可以通过<strong>属性名</strong>访问，代码更可读。</li></ul><hr><h2 id="_2-namedtuple-的方法" tabindex="-1"><a class="header-anchor" href="#_2-namedtuple-的方法" aria-hidden="true">#</a> <strong>2. namedtuple 的方法</strong></h2><table><thead><tr><th>方法</th><th>作用</th></tr></thead><tbody><tr><td><code>._asdict()</code></td><td>将 namedtuple 转换为 <code>OrderedDict</code></td></tr><tr><td><code>._replace(**kwargs)</code></td><td>创建一个新的 namedtuple 实例，修改指定字段值</td></tr><tr><td><code>._fields</code></td><td>返回字段名称的元组</td></tr><tr><td><code>._make(iterable)</code></td><td>通过可迭代对象创建 namedtuple</td></tr></tbody></table><h3 id="示例" tabindex="-1"><a class="header-anchor" href="#示例" aria-hidden="true">#</a> <strong>示例</strong></h3><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token comment"># 1. 使用 _asdict() 转换为字典</span>
<span class="token keyword">print</span><span class="token punctuation">(</span>p<span class="token punctuation">.</span>_asdict<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>  <span class="token comment"># {&#39;name&#39;: &#39;Alice&#39;, &#39;age&#39;: 25, &#39;city&#39;: &#39;New York&#39;}</span>

<span class="token comment"># 2. 使用 _replace() 修改字段值（返回新的 namedtuple）</span>
p2 <span class="token operator">=</span> p<span class="token punctuation">.</span>_replace<span class="token punctuation">(</span>age<span class="token operator">=</span><span class="token number">30</span><span class="token punctuation">)</span>
<span class="token keyword">print</span><span class="token punctuation">(</span>p2<span class="token punctuation">)</span>  <span class="token comment"># Person(name=&#39;Alice&#39;, age=30, city=&#39;New York&#39;)</span>

<span class="token comment"># 3. 查看字段名称</span>
<span class="token keyword">print</span><span class="token punctuation">(</span>Person<span class="token punctuation">.</span>_fields<span class="token punctuation">)</span>  <span class="token comment"># (&#39;name&#39;, &#39;age&#39;, &#39;city&#39;)</span>

<span class="token comment"># 4. 使用 _make() 从列表创建 namedtuple</span>
data <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string">&quot;Bob&quot;</span><span class="token punctuation">,</span> <span class="token number">28</span><span class="token punctuation">,</span> <span class="token string">&quot;Los Angeles&quot;</span><span class="token punctuation">]</span>
p3 <span class="token operator">=</span> Person<span class="token punctuation">.</span>_make<span class="token punctuation">(</span>data<span class="token punctuation">)</span>
<span class="token keyword">print</span><span class="token punctuation">(</span>p3<span class="token punctuation">)</span>  <span class="token comment"># Person(name=&#39;Bob&#39;, age=28, city=&#39;Los Angeles&#39;)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="_3-namedtuple-的应用场景" tabindex="-1"><a class="header-anchor" href="#_3-namedtuple-的应用场景" aria-hidden="true">#</a> <strong>3. namedtuple 的应用场景</strong></h2><h3 id="✅-适用于" tabindex="-1"><a class="header-anchor" href="#✅-适用于" aria-hidden="true">#</a> ✅ <strong>适用于</strong></h3><ul><li><strong>返回多个值</strong>，但又不想用字典（提高可读性）。</li><li><strong>作为轻量级对象</strong>，避免定义类（占用更少的内存）。</li><li><strong>数据不可变</strong>（类似 <code>tuple</code>，不支持修改）。</li></ul><h3 id="❌-不适用于" tabindex="-1"><a class="header-anchor" href="#❌-不适用于" aria-hidden="true">#</a> ❌ <strong>不适用于</strong></h3><ul><li>需要<strong>修改属性</strong>的场景（可以使用 <code>dataclasses</code>）。</li><li>需要<strong>定义方法</strong>的对象（可以使用 <code>class</code>）。</li></ul><hr><h2 id="_4-namedtuple-vs-dataclass" tabindex="-1"><a class="header-anchor" href="#_4-namedtuple-vs-dataclass" aria-hidden="true">#</a> <strong>4. namedtuple vs. dataclass</strong></h2><table><thead><tr><th>特性</th><th><code>namedtuple</code></th><th><code>dataclass</code></th></tr></thead><tbody><tr><td>主要用途</td><td>轻量级不可变对象</td><td>结构化数据类</td></tr><tr><td>是否可变</td><td>❌ 不可变</td><td>✅ 可变（默认）</td></tr><tr><td>可否添加方法</td><td>❌ 不可以</td><td>✅ 可以</td></tr><tr><td>内存占用</td><td>⬇️ 更少</td><td>⬆️ 略多</td></tr><tr><td>适用场景</td><td>仅存储数据，不修改</td><td>需要修改属性、添加方法</td></tr></tbody></table><p>如果你需要<strong>可变对象</strong>，推荐使用 <code>dataclasses</code>：</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">from</span> dataclasses <span class="token keyword">import</span> dataclass

<span class="token decorator annotation punctuation">@dataclass</span>
<span class="token keyword">class</span> <span class="token class-name">Person</span><span class="token punctuation">:</span>
    name<span class="token punctuation">:</span> <span class="token builtin">str</span>
    age<span class="token punctuation">:</span> <span class="token builtin">int</span>
    city<span class="token punctuation">:</span> <span class="token builtin">str</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="总结" tabindex="-1"><a class="header-anchor" href="#总结" aria-hidden="true">#</a> <strong>总结</strong></h2><ul><li><code>namedtuple</code> 是 <code>tuple</code> 的增强版，允许<strong>按名称访问字段</strong>。</li><li><strong>不可变</strong>，适用于<strong>轻量级数据结构</strong>，如坐标、数据库行等。</li><li><strong>主要方法</strong>：<code>_asdict()</code>（转字典）、<code>_replace()</code>（修改值）、<code>_fields</code>（字段列表）。</li><li>如果需要可变对象，可以使用 <code>dataclass</code> 代替。</li></ul>`,26),p=[o];function c(d,l){return s(),a("div",null,p)}const u=n(e,[["render",c],["__file","namedtuple.html.vue"]]);export{u as default};
